func TestBlocksNormalizeEntitiesAndWhitespace(t *testing.T) {
	got, err := ExtractBlocks("<p> Bring  tea &amp;\n biscuits. </p>", nil)
	if err != nil || !reflect.DeepEqual(got, []string{"Bring tea & biscuits."}) {
		t.Fatal(got, err)
	}
}

func TestNoiseRegionsDoNotLeak(t *testing.T) {
	got, err := ExtractBlocks("<head><title>Ignore</title></head><nav>Counter</nav><p>Visible</p><script>run()</script><style>p{}</style><footer>Today</footer>", nil)
	if err != nil || !reflect.DeepEqual(got, []string{"Visible"}) {
		t.Fatal(got, err)
	}
}

func TestQuotedTagDelimiterAndInlineTags(t *testing.T) {
	got, err := ExtractBlocks(`<p title="a > b">A <strong>small</strong> repair</p>`, nil)
	if err != nil || !reflect.DeepEqual(got, []string{"A small repair"}) {
		t.Fatal(got, err)
	}
}

func TestIgnorePhrasesRemoveWholeMatchingBlock(t *testing.T) {
	got, err := ExtractBlocks("<p>Updated today: 44</p><p>Open Thursday</p>", []string{"UPDATED TODAY", ""})
	if err != nil || !reflect.DeepEqual(got, []string{"Open Thursday"}) {
		t.Fatal(got, err)
	}
}

func TestMalformedAndOversizeHTMLFails(t *testing.T) {
	for _, input := range []string{"<p", "<!--missing", "<nav>missing", strings.Repeat("a", MaxHTMLBytes+1), "<>"} {
		if _, err := ExtractBlocks(input, nil); err == nil {
			t.Errorf("accepted malformed input of length %d", len(input))
		}
	}
}

func TestEmptyAndCommentsProduceNoInventedText(t *testing.T) {
	got, err := ExtractBlocks("<!--comment--><p> </p>", nil)
	if err != nil || len(got) != 0 {
		t.Fatal(got, err)
	}
}

func TestSeparateRepeatedBlocksRemainRepeated(t *testing.T) {
	got, err := ExtractBlocks("<p>Repeat</p><p>Repeat</p>", nil)
	if err != nil || !reflect.DeepEqual(got, []string{"Repeat", "Repeat"}) {
		t.Fatal(got, err)
	}
}

func TestCanonicalURLDropsFragmentAndNormalizesHost(t *testing.T) {
	s, e := CanonicalURL("https://EXAMPLE.invalid#section")
	if e != nil || s != "https://example.invalid/" {
		t.Fatal(s, e)
	}
}

func TestURLCredentialsAndUnsupportedSchemesFail(t *testing.T) {
	for _, url := range []string{"file:///tmp/a", "https://user:secret@example.invalid/", "/relative"} {
		if _, e := CanonicalURL(url); e == nil {
			t.Fatal(url)
		}
	}
}

func TestMultisetDifferenceKeepsOccurrenceCounts(t *testing.T) {
	r, e := Compare(snap(t, "<p>A</p><p>A</p><p>B</p>"), snap(t, "<p>A</p><p>B</p><p>C</p>"))
	if e != nil || r.Unchanged != 2 || !reflect.DeepEqual(r.Removed, []Change{{"A", 1}}) || !reflect.DeepEqual(r.Added, []Change{{"C", 1}}) {
		t.Fatal(r, e)
	}
}

func TestReorderedBlocksKeepHashAndNoTextChanges(t *testing.T) {
	a, b := snap(t, "<p>A</p><p>B</p>"), snap(t, "<p>B</p><p>A</p>")
	r, e := Compare(a, b)
	if e != nil || a.Hash != b.Hash || len(r.Added)+len(r.Removed) != 0 {
		t.Fatal(r, e)
	}
}

func TestDifferentURLsCannotBeCompared(t *testing.T) {
	a, b := snap(t, "A"), snap(t, "A")
	b.URL += "?different=1"
	if _, e := Compare(a, b); e == nil {
		t.Fatal("URL mismatch accepted")
	}
}

func TestEmptySnapshotsHaveStableHash(t *testing.T) {
	a, b := snap(t, ""), snap(t, "<!--nothing-->")
	r, e := Compare(a, b)
	if e != nil || a.Hash != b.Hash || r.Unchanged != 0 || len(a.Hash) != 64 {
		t.Fatal(a, b, r, e)
	}
}

func TestNoiseDoesNotChangeContentHash(t *testing.T) {
	a, b := snap(t, "<nav>1</nav><p>A</p>"), snap(t, "<nav>2</nav><p>A</p>")
	if a.Hash != b.Hash {
		t.Fatal(a, b)
	}
}

func TestRedirectPreservesSelectedHTTPS(t *testing.T) {
	for _, tc := range []struct {
		start, target string
		allowed       bool
	}{
		{"https://example.invalid/page", "http://example.invalid/next", false},
		{"https://example.invalid:8443/page", "http://example.invalid:8443/next", false},
		{"https://example.invalid/page", "https://example.invalid/next", true},
		{"http://example.invalid/page", "http://example.invalid/next", true},
		{"http://example.invalid/page", "https://example.invalid/next", true},
		{"https://example.invalid:8443/page", "https://example.invalid:8080/next", false},
		{"https://example.invalid/page", "https://other.invalid/next", false},
	} {
		t.Run(tc.start+" to "+tc.target, func(t *testing.T) {
			calls := 0
			client := &http.Client{Transport: redirectTransport(func(r *http.Request) (*http.Response, error) {
				calls++
				if calls == 1 {
					return &http.Response{StatusCode: 302, Header: http.Header{"Location": {tc.target}}, Body: io.NopCloser(strings.NewReader("redirect")), Request: r}, nil
				}
				return &http.Response{StatusCode: 200, Header: http.Header{"Content-Type": {"text/html"}}, Body: io.NopCloser(strings.NewReader("<p>Current page</p>")), Request: r}, nil
			})}
			body, err := FetchHTML(context.Background(), tc.start, client)
			if tc.allowed {
				if err != nil || calls != 2 || body != "<p>Current page</p>" {
					t.Fatal(body, err, calls)
				}
			} else if err == nil || calls != 1 {
				t.Fatal("redirect target was requested", err, calls)
			}
			if client.CheckRedirect != nil {
				t.Fatal("caller redirect policy mutated")
			}
		})
	}
}

func TestFetchUsesActualHTTPAndReturnsHTML(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "GET" {
			t.Error(r.Method)
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Write([]byte("<p>Library open</p>"))
	}))
	defer server.Close()
	s, e := FetchHTML(context.Background(), server.URL, nil)
	if e != nil || s != "<p>Library open</p>" {
		t.Fatal(s, e)
	}
}

func TestNonOKStatusFails(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { http.Error(w, "Unavailable", 503) }))
	defer server.Close()
	if _, e := FetchHTML(context.Background(), server.URL, nil); e == nil {
		t.Fatal("503 accepted")
	}
}

