func TestCrossHostRedirectAndCancelledContextFail(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, "http://example.invalid/elsewhere", 302)
	}))
	defer server.Close()
	if _, e := FetchHTML(context.Background(), server.URL, nil); e == nil {
		t.Fatal("redirect accepted")
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, e := FetchHTML(ctx, server.URL, nil); e == nil {
		t.Fatal("cancel ignored")
	}
}

func TestSavedSnapshotRoundTripAndNoTemporaryFiles(t *testing.T) {
	s, e := NewSnapshot("https://example.invalid/", "<p>One</p>", nil)
	if e != nil {
		t.Fatal(e)
	}
	dir := t.TempDir()
	path := filepath.Join(dir, "baseline.json")
	if e = SaveSnapshot(path, s); e != nil {
		t.Fatal(e)
	}
	loaded, e := LoadSnapshot(path)
	if e != nil || loaded.Hash != s.Hash || loaded.Blocks[0] != "One" {
		t.Fatal(loaded, e)
	}
	files, _ := os.ReadDir(dir)
	if len(files) != 1 {
		t.Fatal(files)
	}
}

func TestTamperedSnapshotFailsChecksum(t *testing.T) {
	s, _ := NewSnapshot("https://example.invalid/", "<p>One</p>", nil)
	path := filepath.Join(t.TempDir(), "baseline.json")
	SaveSnapshot(path, s)
	data, _ := os.ReadFile(path)
	os.WriteFile(path, []byte(strings.Replace(string(data), "One", "Two", 1)), 0644)
	if _, e := LoadSnapshot(path); e == nil {
		t.Fatal("tampered baseline accepted")
	}
}

func TestExportCreatesHTMLAndJSON(t *testing.T) {
	dir := t.TempDir()
	if e := ExportBrief(example(), dir); e != nil {
		t.Fatal(e)
	}
	for _, name := range []string{"index.html", "changes.json"} {
		if _, e := os.Stat(filepath.Join(dir, name)); e != nil {
			t.Fatal(e)
		}
	}
}

func TestJSONPreservesExactCountsAndSource(t *testing.T) {
	dir := t.TempDir()
	ExportBrief(example(), dir)
	data, _ := os.ReadFile(filepath.Join(dir, "changes.json"))
	var report Brief
	if e := json.Unmarshal(data, &report); e != nil {
		t.Fatal(e)
	}
	if report.Added[0].Count != 2 || report.Removed[0].Text != "Open Thursday" || report.Unchanged != 3 || report.After.URL != "https://example.invalid/" {
		t.Fatal(report)
	}
}

func TestUntrustedTextIsEscaped(t *testing.T) {
	dir := t.TempDir()
	r := example()
	r.Added = []Change{{"<script>alert(1)</script>", 1}}
	ExportBrief(r, dir)
	data, _ := os.ReadFile(filepath.Join(dir, "index.html"))
	if strings.Contains(string(data), "<script>") || !strings.Contains(string(data), "&lt;script&gt;") {
		t.Fatal(string(data))
	}
}

func TestNoChangesHasExplicitEmptyMessage(t *testing.T) {
	dir := t.TempDir()
	r := example()
	r.Added = nil
	r.Removed = nil
	ExportBrief(r, dir)
	data, _ := os.ReadFile(filepath.Join(dir, "index.html"))
	if !strings.Contains(string(data), "No added text.") || !strings.Contains(string(data), "No removed text.") {
		t.Fatal(string(data))
	}
}

func TestInvalidOutputDirectoryPropagatesError(t *testing.T) {
	path := filepath.Join(t.TempDir(), "file")
	os.WriteFile(path, []byte("x"), 0644)
	if e := ExportBrief(example(), path); e == nil {
		t.Fatal("file accepted as output directory")
	}
}

func TestTemplateIncludesBothHashesAndSourceLink(t *testing.T) {
	dir := t.TempDir()
	ExportBrief(example(), dir)
	data, _ := os.ReadFile(filepath.Join(dir, "index.html"))
	for _, text := range []string{"before", "after", `href="https://example.invalid/"`, "Unchanged blocks: 3"} {
		if !strings.Contains(string(data), text) {
			t.Fatal(text)
		}
	}
}
